import { test, expect } from '@playwright/test';

test.describe('Navigation Bar Active Menu Item Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should highlight active menu item in navigation bar', async ({ page }) => {
    // Verify initial state: no active menu item highlighted
    const navLinks = page.getByRole('navigation').locator('[data-testid="nav-link"]');
    await expect(navLinks).toHaveCount(3);
    const activeLink = page.getByRole('navigation').locator('[data-testid="nav-link-active"]');
    await expect(activeLink).not.toBeVisible();

    // Navigate to Home page
    const homeLink = page.getByRole('navigation').locator('[data-testid="nav-link-home"]');
    await homeLink.click();

    // Verify active state is set to Home
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveClass(/active/);

    // Verify other links are not highlighted
    const aboutLink = page.getByRole('navigation').locator('[data-testid="nav-link-about"]');
    await expect(aboutLink).not.toHaveClass(/active/);

    const contactLink = page.getByRole('navigation').locator('[data-testid="nav-link-contact"]');
    await expect(contactLink).not.toHaveClass(/active/);

    // Navigate to Contact page
    const contactLink = page.getByRole('navigation').locator('[data-testid="nav-link-contact"]');
    await contactLink.click();

    // Verify active state is set to Contact
    await expect(contactLink).toBeVisible();
    await expect(contactLink).toHaveClass(/active/);

    // Verify Home link is no longer active
    await expect(homeLink).not.toHaveClass(/active/);

    // Navigate back to Home
    const homeLink = page.getByRole('navigation').locator('[data-testid="nav-link-home"]');
    await homeLink.click();

    // Verify active state is set back to Home
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveClass(/active/);

    // Verify other links are not highlighted
    await expect(aboutLink).not.toHaveClass(/active/);
    await expect(contactLink).not.toHaveClass(/active/);
  });

  test('should not highlight active menu item when page is refreshed', async ({ page }) => {
    // Navigate to About page
    const aboutLink = page.getByRole('navigation').locator('[data-testid="nav-link-about"]');
    await aboutLink.click();

    // Verify active state is set to About
    await expect(aboutLink).toBeVisible();
    await expect(aboutLink).toHaveClass(/active/);

    // Verify Home and Contact links are not highlighted
    const homeLink = page.getByRole('navigation').locator('[data-testid="nav-link-home"]');
    await expect(homeLink).not.toHaveClass(/active/);

    const contactLink = page.getByRole('navigation').locator('[data-testid="nav-link-contact"]');
    await expect(contactLink).not.toHaveClass(/active/);

    // Refresh the page
    await page.reload();

    // Verify active state is not set to About
    await expect(aboutLink).not.toHaveClass(/active/);

    // Verify Home and Contact links are not highlighted
    await expect(homeLink).not.toHaveClass(/active/);
    await expect(contactLink).not.toHaveClass(/active/);

    // Verify Home link is now active
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveClass(/active/);

    // Verify Contact link is not active
    await expect(contactLink).not.toHaveClass(/active/);
  });
});
